def _scenario_multiplier_value(
    multiplier_map: Optional[Mapping[Tuple[Any, ...], Any]],
    candidates: Sequence[Tuple[Any, ...]],
    *,
    default: float = 1.0,
) -> float:
    if not multiplier_map:
        return float(default)
    for key in candidates:
        if key not in multiplier_map:
            continue
        try:
            value = float(multiplier_map[key])
        except (TypeError, ValueError):
            continue
        if np.isfinite(value):
            return max(0.0, value)
    return float(default)


def _emission_factor_multiplier_for_gas(
    multiplier_map: Optional[Mapping[Tuple[Any, ...], Any]],
    *,
    country: str,
    commodity: str,
    process: str,
    year: int,
    ghg: Optional[str],
    default: float = 1.0,
) -> float:
    candidates: List[Tuple[Any, ...]] = []
    if ghg:
        candidates.extend(
            [
                (country, commodity, process, ghg, year),
                (country, commodity, process, 'All', year),
                (country, commodity, 'All', ghg, year),
                (country, 'All', process, ghg, year),
                ('All', commodity, process, ghg, year),
                ('All', 'All', process, ghg, year),
            ]
        )
    else:
        candidates.append((country, commodity, process, 'All', year))
    candidates.extend(
        [
            (country, commodity, process, year),
            (country, commodity, 'All', year),
            (country, 'All', process, year),
            ('All', commodity, process, year),
            ('All', 'All', process, year),
        ]
    )
    return _scenario_multiplier_value(multiplier_map, candidates, default=default)


def _solver_process_emission_multiplier(
    *,
    country: str,
    commodity: str,
    process: str,
    year: int,
    emission_factor_multipliers: Optional[Mapping[Tuple[Any, ...], Any]],
    fertilizer_rate_multipliers: Optional[Mapping[Tuple[Any, ...], Any]],
    ghg_co2eq_by_gas: Optional[Mapping[str, Any]] = None,
) -> float:
    """Return the physical process multiplier used by solver-side costing.

    Gas-specific EF changes are aggregated with BASE gas CO2e shares.  The
    synthetic-fertilizer activity multiplier is then applied multiplicatively,
    matching the emissions module identity ``activity * emission factor``.
    """
    generic_ef = _emission_factor_multiplier_for_gas(
        emission_factor_multipliers,
        country=country,
        commodity=commodity,
        process=process,
        year=year,
        ghg=None,
    )
    gas_components: Dict[str, float] = {}
    for raw_ghg, raw_value in (ghg_co2eq_by_gas or {}).items():
        try:
            value = float(raw_value)
        except (TypeError, ValueError):
            continue
        ghg_name = str(raw_ghg).strip().upper()
        if ghg_name and np.isfinite(value) and value > 0.0:
            gas_components[ghg_name] = gas_components.get(ghg_name, 0.0) + value

    if gas_components:
        component_total = sum(gas_components.values())
        ef_numerator = 0.0
        for ghg_name, component in gas_components.items():
            factor = _emission_factor_multiplier_for_gas(
                emission_factor_multipliers,
                country=country,
                commodity=commodity,
                process=process,
                year=year,
                ghg=ghg_name,
                default=generic_ef,
            )
            ef_numerator += component * factor
        ef_factor = ef_numerator / component_total
    else:
        # When no gas-resolved BASE ledger is available, applying a single
        # explicit gas factor to the aggregate process is safe only if every
        # matching specific-GHG key has the same value.
        specific_values: List[float] = []
        for key, raw_value in (emission_factor_multipliers or {}).items():
            if not isinstance(key, tuple) or len(key) != 5:
                continue
            key_country, key_commodity, key_process, key_ghg, key_year = key
            if str(key_country) not in {str(country), 'All'}:
                continue
            if str(key_commodity) not in {str(commodity), 'All'}:
                continue
            if str(key_process) not in {str(process), 'All'}:
                continue
            if str(key_ghg).strip().lower() == 'all':
                continue
            try:
                if int(key_year) != int(year):
                    continue
                value = float(raw_value)
            except (TypeError, ValueError):
                continue
            if np.isfinite(value):
                specific_values.append(max(0.0, value))
        distinct_values = {round(value, 15) for value in specific_values}
        if len(distinct_values) == 1:
            ef_factor = specific_values[0]
        elif len(distinct_values) > 1:
            raise ValueError(
                "Gas-resolved BASE emissions are required for multiple "
                f"specific-GHG multipliers at {(country, commodity, process, year)}"
            )
        else:
            ef_factor = generic_ef

    fertilizer_factor = 1.0
    if str(process).strip().lower() == 'synthetic fertilizers':
        fertilizer_factor = _scenario_multiplier_value(
            fertilizer_rate_multipliers,
            [
                (country, commodity, year),
                (country, 'All', year),
                ('All', commodity, year),
                ('All', 'All', year),
            ],
        )
    return max(0.0, float(ef_factor) * float(fertilizer_factor))


def _resolve_pipeline_strategy_cost_keys(
    *,
    scenario_id: str,
    scenario_effects: Optional[list],
    scenario_params: Optional[Dict[str, Any]],
    requested_keys: Optional[Sequence[str]],
) -> Tuple[Optional[Tuple[str, ...]], str, Tuple[str, ...]]:
    """Bind one of all nine v2 cost owners to a physical singleton.

    A declared ``ScenarioEffect.strategy_kind`` is authoritative for generic
    process levers. Unambiguous raw system/process levers remain supported for
    direct callers. Multi-strategy scenarios receive the explicit no-owner
    contract because their overlapping tonnes require singleton/Shapley
    attribution. An explicitly requested owner must match the detected
    physical strategy.
    """

    detected: List[str] = []
    observed_effect_kinds: set[str] = set()
    unowned_effect_kinds: set[str] = set()
    scenario_id_text = str(scenario_id)

    def _append_detected(key: Optional[str]) -> None:
        if key and key not in detected:
            detected.append(key)

    for effect in scenario_effects or []:
        if str(getattr(effect, "scenario_id", "")) != scenario_id_text:
            continue
        raw_kind = str(getattr(effect, "kind", "") or "").strip().lower()
        if raw_kind:
            observed_effect_kinds.add(raw_kind)
        declared_kind = str(
            getattr(effect, "strategy_kind", "") or ""
        ).strip().lower()
        if declared_kind:
            declared_key = _COST_STRATEGY_KIND_ALIASES.get(declared_kind)
            if declared_key is None:
                raise ValueError(
                    "ScenarioEffect declares an unknown v2 strategy_kind "
                    f"{declared_kind!r} in scenario {scenario_id!r}"
                )
            raw_system_key = _SYSTEM_COST_KIND_ALIASES.get(raw_kind)
            if raw_system_key and raw_system_key != declared_key:
                raise ValueError(
                    "ScenarioEffect strategy metadata conflicts with its "
                    f"physical kind in scenario {scenario_id!r}: "
                    f"strategy_kind={declared_kind!r}, kind={raw_kind!r}"
                )
            _append_detected(declared_key)
            # Generic emission-factor and management levers are fully owned by
            # the declared strategy and must not be mistaken for a coalition.
            continue

        key = _SYSTEM_COST_KIND_ALIASES.get(raw_kind)
        if key is None:
            key = _PROCESS_COST_EFFECT_KIND_ALIASES.get(raw_kind)
        if key is None and raw_kind == "emission_factor":
            process_selector = str(
                getattr(
                    effect,
                    "process_selector",
                    getattr(effect, "process_sel", ""),
                )
                or ""
            ).strip().lower()
            key = _PROCESS_SELECTOR_COST_ALIASES.get(process_selector)
        if key:
            _append_detected(key)
        elif raw_kind:
            unowned_effect_kinds.add(raw_kind)

    param_key_map = {
        "ruminant_intake_cap": "RuminantReduction",
        "losses_ratio_by": "LossWaste",
        "waste_reduction_rate_by": "LossWaste",
        "yield_multiplier": "YieldRate",
        "yield_absolute_by": "YieldRate",
        "dm_conversion_multiplier": "FeedEfficiency",
        "dm_conversion_multiplier_ipcc": "FeedEfficiency",
        "dm_conversion_multiplier_gleam": "FeedEfficiency",
        "fertilizer_rate_multiplier": "Fertilizer",
        "fertilizer_efficiency_absolute_by": "Fertilizer",
        "manure_management_ratio_multiplier": "Manure",
        "manure_management_ratio_absolute_by": "Manure",
        "crop_soil_management_multiplier": "Residue",
    }
    feed_efficiency_companion_params = {
        "feed_reduction_by",
        "feed_reduction_by_ipcc",
        "feed_reduction_by_gleam",
    }
    nonempty_param_names: set[str] = set()
    if isinstance(scenario_params, dict):
        for param_name, key in param_key_map.items():
            value = scenario_params.get(param_name)
            if value:
                _append_detected(key)
                nonempty_param_names.add(param_name)
        for param_name, value in scenario_params.items():
            if param_name in param_key_map:
                continue
            try:
                has_value = bool(value)
            except (TypeError, ValueError):
                has_value = True
            if has_value:
                nonempty_param_names.add(str(param_name))

    detected_tuple = tuple(detected)
    has_unowned_effect = bool(unowned_effect_kinds)
    allowed_strategy_param_names = set(param_key_map)
    if "FeedEfficiency" in detected_tuple:
        # These legacy signed-rate fields are emitted alongside the canonical
        # DM multiplier by the new scenario builder, but by themselves they
        # modify final livestock demand and do not prove FeedEfficiency.
        allowed_strategy_param_names.update(feed_efficiency_companion_params)
    has_unowned_effect = has_unowned_effect or any(
        name not in allowed_strategy_param_names for name in nonempty_param_names
    )
    if requested_keys is None:
        if len(detected_tuple) == 1 and not has_unowned_effect:
            return (detected_tuple[0],), "scenario_inferred_singleton", detected_tuple
        if detected_tuple:
            return (), "scenario_inferred_coalition_no_owner", detected_tuple
        return None, "legacy_process_default", detected_tuple

    normalized = tuple(
        dict.fromkeys(str(key).strip() for key in requested_keys if str(key).strip())
    )
    unknown = sorted(set(normalized) - set(COST_DATABASE_V2_KEYS))
    if unknown:
        raise ValueError(f"Unknown v2 cost strategy key(s): {unknown}")
    if len(normalized) > 1:
        raise ValueError(
            "A solve may own at most one mitigation-cost strategy; "
            "use singleton/Shapley attribution for combinations"
        )
    if normalized and detected_tuple and normalized != detected_tuple:
        raise ValueError(
            "The requested v2 cost owner does not match the physical "
            f"strategy in scenario {scenario_id!r}: requested={normalized}, "
            f"detected={detected_tuple}"
        )
    if normalized and not detected_tuple:
        raise ValueError(
            "A v2 cost owner requires a matching physical "
            f"scenario effect: requested={normalized[0]!r}, scenario={scenario_id!r}"
        )
    if normalized and has_unowned_effect:
        raise ValueError(
            "A v2 cost owner requires a strict physical singleton; "
            f"scenario {scenario_id!r} also contains unowned effects "
            f"{sorted(unowned_effect_kinds)}"
        )
    return normalized, "explicit", detected_tuple


