def _validate_base_emissions_reference(
    run_dir: Path,
    *,
    expected_scenario_id: str,
) -> Dict[str, Any]:
    """Validate a BASE emissions ledger against its terminal content digest."""
    validation = validate_run_for_resume(
        run_dir,
        expected_scenario_id=expected_scenario_id,
    )
    if not validation.allowed:
        return {
            "allowed": False,
            "reason": f"run_status:{validation.reason}",
            "run_id": validation.run_id,
            "sha256": "",
        }

    payload = validation.payload or {}
    emissions = payload.get("emissions")
    artifacts = emissions.get("artifacts") if isinstance(emissions, Mapping) else None
    declaration = (
        artifacts.get("by_country_process_item")
        if isinstance(artifacts, Mapping)
        else None
    )
    if not isinstance(declaration, Mapping):
        return {
            "allowed": False,
            "reason": "missing_emissions_ledger_integrity_declaration",
            "run_id": validation.run_id,
            "sha256": "",
        }
    artifact_validation = validate_artifact_integrity_declaration(
        run_dir,
        declaration,
        validation,
    )
    return {
        "allowed": bool(artifact_validation.allowed),
        "reason": (
            "ok"
            if artifact_validation.allowed
            else f"emissions_ledger:{artifact_validation.reason}"
        ),
        "run_id": validation.run_id,
        "sha256": str(declaration.get("sha256", "") or ""),
        "declaration": dict(declaration),
    }


class _DedupFilter(logging.Filter):
    """Filter duplicate log messages so each distinct message is recorded once."""
    _seen_messages = set()
    def filter(self, record: logging.LogRecord) -> bool:
        msg = record.getMessage()
        if msg in self._seen_messages:
            return False
        self._seen_messages.add(msg)
        return True


