def _get_debug_level() -> int:
    raw_env = os.environ.get("NZF_DEBUG_LEVEL", "").strip()
    if raw_env:
        try:
            return max(0, int(float(raw_env)))
        except Exception:
            pass
    try:
        return max(0, int(CFG.get('debug_level', 0) or 0))
    except Exception:
        return 0


def _normalize_m49_cache_key(value: Any) -> str:
    if value is None or pd.isna(value):
        return ''
    s = str(value).strip()
    if not s:
        return ''
    if s.startswith("'"):
        s = s[1:]
    s = s.strip()
    if not s:
        return ''
    if s.count('.') == 1:
        left, right = s.split('.', 1)
        if left.isdigit() and right.strip('0') == '':
            s = left
    if s.isdigit():
        return f"'{s.zfill(3)}"
    return f"'{s}"


def _get_region_label_map(dict_v3_path: Optional[str]) -> Dict[str, str]:
    if not dict_v3_path:
        return {}
    try:
        cache_key = str(Path(dict_v3_path).resolve())
    except Exception:
        cache_key = str(dict_v3_path)
    cached = _REGION_LABEL_CACHE.get(cache_key)
    if cached is not None:
        return cached
    region_label_map: Dict[str, str] = {}
    if os.path.exists(dict_v3_path):
        try:
            region_df = _read_dict_v3_sheet(
                dict_v3_path,
                'region',
                usecols=['M49_Country_Code', 'Region_label_new'],
            )
            region_df = region_df.dropna(subset=['M49_Country_Code'])
            region_df['M49_Country_Code'] = region_df['M49_Country_Code'].map(_normalize_m49_cache_key)
            region_label_map = dict(zip(region_df['M49_Country_Code'], region_df['Region_label_new']))
        except Exception:
            region_label_map = {}
    _REGION_LABEL_CACHE[cache_key] = region_label_map
    return region_label_map


def _get_static_driver_bundle(paths: DataPaths, universe: Universe) -> Dict[str, Any]:
    from S2_0_load_data import (
        load_population_wpp,
        load_nutrient_factors_from_dict_v3,
        load_intake_targets,
        load_income_multipliers_from_sspdb,
    )

    cache_key = (
        str(Path(paths.population_wpp_csv).resolve()) if paths.population_wpp_csv else '',
        str(Path(paths.intake_constraint_xlsx).resolve()) if paths.intake_constraint_xlsx else '',
        str(Path(paths.dict_v3_path).resolve()) if paths.dict_v3_path else '',
        str(Path(paths.income_sspdb_xlsx).resolve()) if paths.income_sspdb_xlsx else '',
        str(Path(paths.inputs_landuse_csv).resolve()) if paths.inputs_landuse_csv else '',
        str(CFG.get('intake_indicator', 'energy') or 'energy'),
        str(CFG.get('intake_constraint_value_col') or ''),
        str(paths.sspdb_scenario or ''),
        tuple(int(y) for y in universe.years),
        tuple(str(c) for c in universe.countries),
    )
    cached = _STATIC_DRIVER_CACHE.get(cache_key)
    if cached is not None:
        return cached

    pop_map = load_population_wpp(paths.population_wpp_csv, universe)
    intake_targets = load_intake_targets(
        paths.intake_constraint_xlsx,
        CFG['intake_indicator'],
        CFG.get('intake_constraint_value_col'),
    )
    nutrient_energy_map = load_nutrient_factors_from_dict_v3(paths.dict_v3_path, 'energy')
    nutrient_protein_map = load_nutrient_factors_from_dict_v3(paths.dict_v3_path, 'protein')
    nutrient_map = load_nutrient_factors_from_dict_v3(paths.dict_v3_path, CFG['intake_indicator'])
    inc_mult = load_income_multipliers_from_sspdb(paths.income_sspdb_xlsx, paths.sspdb_scenario, universe)
    land_limits = load_land_area_limits(paths.inputs_landuse_csv)
    land_src_cols: List[str] = []
    try:
        if os.path.exists(paths.inputs_landuse_csv):
            land_src_cols = list(read_csv_cached(paths.inputs_landuse_csv, nrows=1).columns)
    except Exception:
        land_src_cols = []

    bundle = {
        'pop_map': pop_map,
        'intake_targets': intake_targets,
        'nutrient_energy_map': nutrient_energy_map,
        'nutrient_protein_map': nutrient_protein_map,
        'nutrient_map': nutrient_map,
        'inc_mult': inc_mult,
        'land_limits': land_limits,
        'land_src_cols': land_src_cols,
    }
    _STATIC_DRIVER_CACHE[cache_key] = bundle
    return bundle


def refresh_runtime_caches(*, reload_dict_relations: bool = True) -> None:
    """Clear in-process caches so updated inputs/dict_v3 mappings take effect without restarting."""
    global item_maps

    _STATIC_DRIVER_CACHE.clear()
    _REGION_LABEL_CACHE.clear()
    _BASE_REFERENCE_CACHE.clear()
    _PIPELINE_STATIC_CACHE.clear()

    try:
        import runtime_data_cache as _runtime_cache
        _runtime_cache.clear_memory_caches()
    except Exception:
        pass

    try:
        from S2_0_load_data import _excel_sheet_names_cached, _read_excel_cached_impl, _read_csv_cached_impl
        _excel_sheet_names_cached.cache_clear()
        _read_excel_cached_impl.cache_clear()
        _read_csv_cached_impl.cache_clear()
    except Exception:
        pass

    try:
        from S3_6_scenarios import _read_scenario_range_sheet
        _read_scenario_range_sheet.cache_clear()
    except Exception:
        pass

    if reload_dict_relations:
        item_maps = load_emis_item_mappings(paths.dict_v3_path)
# helpers
def _is_lulucf_process(name: str, meta_map: dict) -> bool:
    mm = (meta_map or {}).get(name, {})
    cat = str(mm.get('category') or mm.get('Category') or mm.get('sector') or '').lower()
    name_l = (name or '').lower()
    return ('lulu' in cat) or ('forest' in name_l) or ('savanna' in name_l) or ('drained organic' in name_l) or ('net forest' in name_l)


def _is_explicit_land_emission_process(name: Any) -> bool:
    """Processes recalculated by explicit land/fire/soil modules, not node e0 output."""
    name_l = str(name or '').strip().lower()
    if not name_l:
        return False
    return any(token in name_l for token in (
        'de/reforestation',
        'ag land abandonment',
        'abandonment',
        'reforestation',
        'wood harvest',
        'forest',
        'savanna fire',
        'savanna fires',
        'peatlands fire',
        'peatland fire',
        'drained organic',
        'organic soils',
    ))
import pickle
def _load_macc_df(path: str = os.path.join(get_input_base(), 'MACC-Global-US.pkl')) -> pd.DataFrame:
    try:
        return pickle.load(open(path, 'rb'))
    except Exception:
        return pd.DataFrame()
def _build_coarse_transitions_from_deltas(deltas: Optional[pd.DataFrame],
                                          iso_map: Dict[str, str]) -> pd.DataFrame:
    columns = ['country', 'iso3', 'year',
               'forest_to_cropland', 'forest_to_pasture',
               'cropland_to_forest', 'pasture_to_forest']
    if not isinstance(deltas, pd.DataFrame) or deltas.empty:
        return pd.DataFrame(columns=columns)
    df = deltas.copy()
    if 'iso3' in df.columns and df['iso3'].notna().any():
        df['iso3'] = df['iso3'].astype(str)
        if 'M49_Country_Code' in df.columns:
            df['M49_Country_Code'] = df['M49_Country_Code'].apply(_infer_m49_code)
            df['iso3'] = df['iso3'].fillna(df['M49_Country_Code'].map(iso_map))
        if df['iso3'].isna().any():
            df['iso3'] = df['iso3'].fillna(df['country'].map(iso_map))
    else:
        df['iso3'] = ''
        if 'M49_Country_Code' in df.columns:
            df['M49_Country_Code'] = df['M49_Country_Code'].apply(_infer_m49_code)
            df['iso3'] = df['M49_Country_Code'].map(iso_map)
        if df['iso3'].isna().any() or (df['iso3'].astype(str).str.strip() == '').any():
            df['iso3'] = df['iso3'].fillna(df['country'].map(iso_map))
    df = df.dropna(subset=['iso3'])
    records: List[Dict[str, Any]] = []
    for row in df.itertuples(index=False):
        try:
            country = str(getattr(row, 'country'))
            iso3 = str(getattr(row, 'iso3'))
            year = int(getattr(row, 'year'))
            dc = float(getattr(row, 'd_cropland_ha', 0.0) or 0.0)
            dg = float(getattr(row, 'd_grassland_ha', 0.0) or 0.0)
            df_forest = float(getattr(row, 'd_forest_ha', 0.0) or 0.0)
        except Exception:
            continue
        fc = max(dc, 0.0)
        fp = max(dg, 0.0)
        cf = max(-dc, 0.0)
        pf = max(-dg, 0.0)
        forest_loss = max(-df_forest, 0.0)
        forest_gain = max(df_forest, 0.0)
        if fc + fp > 0.0:
            if forest_loss > 0.0:
                scale = forest_loss / (fc + fp)
                fc *= scale
                fp *= scale
            else:
                fc = 0.0
                fp = 0.0
        if cf + pf > 0.0:
            if forest_gain > 0.0:
                scale = forest_gain / (cf + pf)
                cf *= scale
                pf *= scale
            else:
                cf = 0.0
                pf = 0.0
        if (fc + fp + cf + pf) <= 0.0:
            continue
        records.append({
            'country': country,
            'iso3': iso3,
            'year': year,
            'forest_to_cropland': max(fc, 0.0),
            'forest_to_pasture': max(fp, 0.0),
            'cropland_to_forest': max(cf, 0.0),
            'pasture_to_forest': max(pf, 0.0),
        })
    if not records:
        return pd.DataFrame(columns=columns)
    out = pd.DataFrame.from_records(records, columns=columns)
    return out.groupby(['country', 'iso3', 'year'], as_index=False).sum()


def _build_land_transition_frames_from_linear_result(
    linear_result: Optional[Dict[str, Any]],
    universe: Any,
) -> Tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame]:
    """Build LUC gross transitions and land deltas from solved land conversion vars."""
    coarse_cols = [
        'M49_Country_Code', 'country', 'iso3', 'year',
        'forest_to_cropland', 'forest_to_pasture',
        'cropland_to_forest', 'pasture_to_forest',
        'grassland_to_cropland', 'cropland_to_grassland',
        'cropland_to_othernat', 'pasture_to_othernat',
    ]
    delta_cols = [
        'M49_Country_Code', 'country', 'iso3', 'year',
        'd_cropland_ha', 'd_grassland_ha', 'd_forest_ha',
        'nonforest_to_cropland_ha', 'nonforest_to_grassland_ha',
    ]
    full_cols = coarse_cols + [
        'nonforest_to_cropland', 'nonforest_to_grassland',
        'solver_forest_to_cropland', 'solver_forest_to_pasture',
        'background_forest_to_cropland', 'background_forest_to_pasture',
        'background_cropland_to_forest', 'background_pasture_to_forest',
    ]
    if not isinstance(linear_result, dict):
        return pd.DataFrame(columns=coarse_cols), pd.DataFrame(columns=delta_cols), pd.DataFrame(columns=full_cols)

    country_by_m49 = getattr(universe, 'country_by_m49', {}) or {}
    iso3_by_country = getattr(universe, 'iso3_by_country', {}) or {}
    m49_by_country = getattr(universe, 'm49_by_country', {}) or {}

    def _meta_for_region(region: Any) -> Tuple[Optional[str], str, str]:
        region_text = str(region).strip()
        m49 = _infer_m49_code(region)
        country = ''
        if m49:
            country = str(country_by_m49.get(m49, '') or '').strip()
        if not country and region_text in m49_by_country:
            country = region_text
            m49 = _infer_m49_code(m49_by_country.get(region_text))
        if not country:
            country = region_text
        iso3 = str(iso3_by_country.get(country, '') or '').strip()
        return m49, country, iso3

    source_map = {
        'forest_to_cropland': ('forest_to_cropland', 'solver_forest_to_cropland'),
        'forest_to_grassland': ('forest_to_pasture', 'solver_forest_to_pasture'),
        'background_forest_to_cropland': ('forest_to_cropland', 'background_forest_to_cropland'),
        'background_forest_to_grassland': ('forest_to_pasture', 'background_forest_to_pasture'),
        'background_cropland_to_forest': ('cropland_to_forest', 'background_cropland_to_forest'),
        'background_grassland_to_forest': ('pasture_to_forest', 'background_pasture_to_forest'),
        'cropland_to_forest': ('cropland_to_forest', None),
        'grassland_to_forest': ('pasture_to_forest', None),
        'grassland_to_cropland': ('grassland_to_cropland', None),
        'cropland_to_grassland': ('cropland_to_grassland', None),
        'cropland_to_othernat': ('cropland_to_othernat', None),
        'grassland_to_othernat': ('pasture_to_othernat', None),
        'nonforest_to_cropland': ('nonforest_to_cropland', None),
        'nonforest_to_grassland': ('nonforest_to_grassland', None),
    }
    rows_by_key: Dict[Tuple[str, str, str, int], Dict[str, Any]] = {}
    for result_key, out_spec in source_map.items():
        out_col, diag_col = out_spec
        raw_map = linear_result.get(result_key)
        if not isinstance(raw_map, dict):
            continue
        for key, val in raw_map.items():
            if not isinstance(key, tuple) or len(key) < 2:
                continue
            try:
                area_val = float(val or 0.0)
                year_val = int(key[1])
            except Exception:
                continue
            if not np.isfinite(area_val) or abs(area_val) <= 0.0:
                continue
            m49, country, iso3 = _meta_for_region(key[0])
            if not m49:
                continue
            row_key = (m49, country, iso3, year_val)
            row = rows_by_key.get(row_key)
            if row is None:
                row = {
                    'M49_Country_Code': m49,
                    'country': country,
                    'iso3': iso3,
                    'year': year_val,
                }
                rows_by_key[row_key] = row
            area_pos = max(area_val, 0.0)
            row[out_col] = float(row.get(out_col, 0.0) or 0.0) + area_pos
            if diag_col:
                row[diag_col] = float(row.get(diag_col, 0.0) or 0.0) + area_pos

    if not rows_by_key:
        return pd.DataFrame(columns=coarse_cols), pd.DataFrame(columns=delta_cols), pd.DataFrame(columns=full_cols)

    full = pd.DataFrame.from_records(list(rows_by_key.values()))
    for col in full_cols:
        if col not in full.columns:
            full[col] = 0.0 if col not in {'M49_Country_Code', 'country', 'iso3', 'year'} else full.get(col, '')
    num_cols = [c for c in full_cols if c not in {'M49_Country_Code', 'country', 'iso3', 'year'}]
    for col in num_cols:
        full[col] = pd.to_numeric(full[col], errors='coerce').fillna(0.0).clip(lower=0.0)
    if bool(CFG.get('clean_solver_land_conversion_cycles_for_luc', True)):
        cycle_removed_ha = 0.0
        cycle_remapped_ha = 0.0

        def _take_pair(row_idx: Any, from_col: str, to_col: str) -> float:
            nonlocal cycle_removed_ha
            amt = min(float(full.at[row_idx, from_col] or 0.0), float(full.at[row_idx, to_col] or 0.0))
            if amt > 0.0:
                full.at[row_idx, from_col] = max(0.0, float(full.at[row_idx, from_col] or 0.0) - amt)
                full.at[row_idx, to_col] = max(0.0, float(full.at[row_idx, to_col] or 0.0) - amt)
                cycle_removed_ha += 2.0 * amt
            return amt

        def _remap_forest_bridge(row_idx: Any, ag_to_forest: str, forest_to_ag: str, direct_col: str) -> float:
            nonlocal cycle_remapped_ha
            amt = min(float(full.at[row_idx, ag_to_forest] or 0.0), float(full.at[row_idx, forest_to_ag] or 0.0))
            if amt > 0.0:
                full.at[row_idx, ag_to_forest] = max(0.0, float(full.at[row_idx, ag_to_forest] or 0.0) - amt)
                full.at[row_idx, forest_to_ag] = max(0.0, float(full.at[row_idx, forest_to_ag] or 0.0) - amt)
                full.at[row_idx, direct_col] = float(full.at[row_idx, direct_col] or 0.0) + amt
                cycle_remapped_ha += amt
            return amt

        def _net_land_class(row_idx: Any, in_cols: List[str], out_cols: List[str]) -> None:
            nonlocal cycle_removed_ha
            in_total = sum(float(full.at[row_idx, c] or 0.0) for c in in_cols)
            out_total = sum(float(full.at[row_idx, c] or 0.0) for c in out_cols)
            cancel = min(in_total, out_total)
            if cancel <= 0.0:
                return
            if in_total > 0.0:
                in_scale = max(0.0, (in_total - cancel) / in_total)
                for c in in_cols:
                    full.at[row_idx, c] = float(full.at[row_idx, c] or 0.0) * in_scale
            if out_total > 0.0:
                out_scale = max(0.0, (out_total - cancel) / out_total)
                for c in out_cols:
                    full.at[row_idx, c] = float(full.at[row_idx, c] or 0.0) * out_scale
            cycle_removed_ha += 2.0 * cancel

        for row_idx in full.index:
            # Same-pair forest loops cancel directly.
            _take_pair(row_idx, 'cropland_to_forest', 'forest_to_cropland')
            _take_pair(row_idx, 'pasture_to_forest', 'forest_to_pasture')
            # Forest-mediated crop<->pasture swaps are represented as direct
            # crop<->grass conversion so LUC accounting does not count a
            # spurious reforestation+deforestation pair in the same region-year.
            _remap_forest_bridge(row_idx, 'cropland_to_forest', 'forest_to_pasture', 'cropland_to_grassland')
            _remap_forest_bridge(row_idx, 'pasture_to_forest', 'forest_to_cropland', 'grassland_to_cropland')
            # Finally keep only the net in/out direction per agricultural land
            # class; this is the LP-safe counterpart to pairwise no-cycle
            # complementarity.
            _net_land_class(
                row_idx,
                ['forest_to_cropland', 'grassland_to_cropland', 'nonforest_to_cropland'],
                ['cropland_to_forest', 'cropland_to_grassland', 'cropland_to_othernat'],
            )
            _net_land_class(
                row_idx,
                ['forest_to_pasture', 'cropland_to_grassland', 'nonforest_to_grassland'],
                ['pasture_to_forest', 'grassland_to_cropland', 'pasture_to_othernat'],
            )
        if cycle_removed_ha > 0.0 or cycle_remapped_ha > 0.0:
            logging.getLogger(__name__).info(
                "[LUC SOLVER-FLOWS] cleaned same region-year gross conversion cycles: "
                "removed=%.6g ha remapped_forest_bridge=%.6g ha",
                cycle_removed_ha,
                cycle_remapped_ha,
            )
    full = full[full_cols].sort_values(['M49_Country_Code', 'year']).reset_index(drop=True)

    coarse = full[coarse_cols].copy()
    coarse = coarse[
        (coarse[[
            'forest_to_cropland', 'forest_to_pasture',
            'cropland_to_forest', 'pasture_to_forest',
            'grassland_to_cropland', 'cropland_to_grassland',
            'cropland_to_othernat', 'pasture_to_othernat',
        ]].sum(axis=1) > 0)
    ].reset_index(drop=True)

    deltas = full[['M49_Country_Code', 'country', 'iso3', 'year']].copy()
    deltas['d_cropland_ha'] = (
        full['forest_to_cropland']
        + full['grassland_to_cropland']
        + full['nonforest_to_cropland']
        - full['cropland_to_forest']
        - full['cropland_to_grassland']
        - full['cropland_to_othernat']
    )
    deltas['d_grassland_ha'] = (
        full['forest_to_pasture']
        + full['cropland_to_grassland']
        + full['nonforest_to_grassland']
        - full['pasture_to_forest']
        - full['grassland_to_cropland']
        - full['pasture_to_othernat']
    )
    deltas['d_forest_ha'] = (
        full['cropland_to_forest']
        + full['pasture_to_forest']
        - full['forest_to_cropland']
        - full['forest_to_pasture']
    )
    deltas['nonforest_to_cropland_ha'] = full['nonforest_to_cropland']
    deltas['nonforest_to_grassland_ha'] = full['nonforest_to_grassland']
    deltas = deltas[delta_cols].sort_values(['M49_Country_Code', 'year']).reset_index(drop=True)
    return coarse, deltas, full


def _resolve_luc_coupling_mode(cfg: Dict[str, Any]) -> str:
    """Normalize the high-level LUC coupling mode used by S4 postprocessing."""
    raw = str(cfg.get('luc_coupling_mode', 'solver_luc') or 'solver_luc').strip().lower()
    aliases = {
        'qs': 'qs_demand',
        'qsdemand': 'qs_demand',
        'qs_demand': 'qs_demand',
        'demand_delta': 'qs_demand',
        'solver': 'solver_luc',
        'solver_land': 'solver_luc',
        'solver_land_state': 'solver_luc',
        'solver_luc': 'solver_luc',
        'opt': 'optimize_luc',
        'opt_luc': 'optimize_luc',
        'optimize': 'optimize_luc',
        'optimize_luc': 'optimize_luc',
    }
    return aliases.get(raw, 'solver_luc')


